CREATE TABLE IF NOT EXISTS recruiter_featured (city_id INTEGER PRIMARY KEY, city_name TEXT NOT NULL, position_ids TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activation_config (id INTEGER PRIMARY KEY CHECK (id=1), paused INTEGER NOT NULL DEFAULT 0, schedule_time TEXT NOT NULL DEFAULT '10:07', freeze_days INTEGER NOT NULL DEFAULT 14, auto_review INTEGER NOT NULL DEFAULT 0, daily_limit INTEGER NOT NULL DEFAULT 20, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
